html:
{% if doc.scan_code_label %}
{% set base = frappe.utils.get_url() ~ "/api/method/asn_module.qr_engine.generate.scan_image?code=" ~ (doc.scan_code_label | urlencode) %}
<div>
	<img src="{{ base }}&kind=qr" alt="{{ _('ASN QR') }}" style="max-height: 200px;">
	<img src="{{ base }}&kind=barcode" alt="{{ _('ASN barcode') }}" style="max-height: 120px;">
</div>
{% endif %}
